function normalizeSearch(value){return String(value??'').toLocaleLowerCase('tr').replace(/ı/g,'i').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim()}
function recordSearchText(doc,client){const fields=record=>Object.entries(record||{}).filter(([key,value])=>!['id','client','fileData'].includes(key)&&['string','number'].includes(typeof value)).flatMap(([key,value])=>{const out=[value];if(/date|due|issued|created|period/i.test(key)){const date=String(value).slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(date))out.push(date.split('-').reverse().join('.'),date.split('-').reverse().join('/'))}return out});const staff=typeof personnel==='undefined'?[]:personnel.filter(p=>[client?.documentStaff,client?.collectionStaff].includes(p.id)).map(p=>p.name);const amount=Number(doc.amount||0);return normalizeSearch([...fields(doc),...fields(client),...staff,docType(doc),String(amount),amount.toFixed(2),new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2}).format(amount)].join(' '))}
function borrowerPhoneMatches(doc,query){const digits=value=>String(value||'').replace(/\D/g,''),needle=digits(query);if(!needle)return true;const phones=[doc.phone1,doc.phone2,doc.referencePhone1,doc.referencePhone2,doc.officePhone1,doc.officePhone2,...(doc.additionalPhones||[])];return phones.some(phone=>{const value=digits(phone);return value.includes(needle)||(needle.startsWith('90')&&value.replace(/^0/,'').includes(needle.slice(2)))||(needle.startsWith('0')&&value.replace(/^90/,'').replace(/^0/,'').includes(needle.slice(1)))})}
function matchesGlobalSearch(doc,client,query){const text=recordSearchText(doc,client);if(normalizeSearch(query).split(/\s+/).filter(Boolean).every(term=>text.includes(term)))return true;return /^[+\d\s().-]+$/.test(String(query||''))&&String(query).replace(/\D/g,'').length>=3&&borrowerPhoneMatches(doc,query)}
