function receipt(id){let d=db.docs.find(x=>x.id===id),c=db.clients.find(x=>x.id===d.client);$('#modal').innerHTML=`<div class="receipt"><p class="eyebrow">hanhukuk 1.1.1 · EVRAK KABUL</p>${firmReceipt()}<h2>${esc(docType(d))} Teslim Tutanağı</h2><p><b>Evrak No:</b> ${esc(d.number)}<br><b>Kabul Tarihi:</b> ${new Date(d.created).toLocaleDateString('tr-TR')}<br><b>Müvekkil:</b> ${esc(c?.name)}<br><b>Borçlu:</b> ${esc(d.debtor)}<br><b>Evrak Aslı:</b> ${esc(d.originalDocument||'Belirtilmedi')}<br><b>Evrak No / Referans:</b> ${esc(d.serial||'—')}${documentExtraReceipt(d)}<br><b>Tutar:</b> ${money(d.amount)}<br><b>Vade:</b> ${esc(d.due?displayDate(d.due):'—')}</p><p><b>Tel-1 / Tel-2:</b> ${esc(d.phone1||'—')} / ${esc(d.phone2||'—')}<br><b>Ref. Tel-1 / Tel-2:</b> ${esc(d.referencePhone1||'—')} / ${esc(d.referencePhone2||'—')}<br><b>Ofis Tel-1 / Tel-2:</b> ${esc(d.officePhone1||'—')} / ${esc(d.officePhone2||'—')}<br><b>Adres:</b> ${esc([d.address,d.district,d.city].filter(Boolean).join(' / '))}<br><b>Borçlu Adres-2:</b> ${esc([d.address2,d.address2District,d.address2City].filter(Boolean).join(' / ')||'—')}<br><b>Borçlu Adres (Ofis)-3:</b> ${esc([d.officeAddress3,d.officeAddress3District,d.officeAddress3City].filter(Boolean).join(' / ')||'—')}</p><p><b>Dosya Sorumlusu:</b> ${esc(personnel.find(p=>p.id===d.relatedStaff)?.name||d.relatedStaffName||'—')}<br><b>Teslim Eden:</b> ${esc(d.deliveredBy)}<br><b>Teslim Alan:</b> ${esc(d.receivedBy)}</p><p><b>Kabul Notu:</b> ${esc(d.notes||'—')}</p>${d.fileData?`<p><a href="${d.fileData}" download="${esc(d.fileName)}">Ekli evrakı indir: ${esc(d.fileName)}</a></p>`:''}${d.photoData?`<p><a href="${d.photoData}" download="${esc(d.photoFileName||'fotograf')}">Fotoğrafı indir: ${esc(d.photoFileName||'Fotoğraf')}</a></p>`:''}<div class="grid" style="margin-top:35px"><div>Teslim Eden İmza<br>________________</div><div>Teslim Alan İmza<br>________________</div></div><p style="font-size:11px;color:#8a95a2;margin-top:30px">Prototip çıktısıdır. Resmî işlem veya elektronik imza içermez.</p></div><div class="actions"><button class="secondary" id="closeReceipt">Kapat</button><button class="primary" id="print">Yazdır / PDF</button></div>`;$('#modal').showModal();$('#closeReceipt').onclick=()=>$('#modal').close();$('#print').onclick=()=>window.print()}
