function intakeBatchReceipt(){const ids=intakeBatchIds(),docs=ids.map(id=>db.docs.find(d=>d.id===id));if(!docs.length)return toast('Bu teslim grubunda henüz kaydedilmiş evrak yok.');const total=docs.reduce((sum,d)=>sum+financeCents(d.amount),0);$('#modal').innerHTML=`<div class="receipt">${firmReceipt()}<h2>Teslim Tesellüm Tutanağı</h2><p>Tarih: ${displayDate(businessDate())} · Evrak adedi: ${docs.length}</p><div class="overflow"><table><thead><tr><th>SIRA</th><th>EVRAK NO / TÜR</th><th>MÜVEKKİL</th><th>BORÇLU</th><th>VADE</th><th>EVRAK ASLI</th><th>TUTAR</th></tr></thead><tbody>${docs.map((d,i)=>`<tr><td>${i+1}</td><td>${esc(d.number)}<small>${esc(docType(d))}</small></td><td>${esc(db.clients.find(c=>c.id===d.client)?.name||'—')}</td><td>${esc(d.debtor)}</td><td>${esc(displayDate(d.due)||'—')}</td><td>${esc(d.originalDocument||'—')}</td><td>${money(d.amount)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="6"><b>TOPLAM</b></td><td><b>${money(total/100)}</b></td></tr></tfoot></table></div><div class="grid" style="margin-top:35px"><div>Teslim Eden: ${esc([...new Set(docs.map(d=>d.deliveredBy).filter(Boolean))].join(', '))}<br>İmza: __________________</div><div>Teslim Alan: ${esc([...new Set(docs.map(d=>d.receivedBy).filter(Boolean))].join(', '))}<br>İmza: __________________</div></div><p>Yukarıda listelenen evraklar belirtilen asıl durumlarıyla teslim edilmiştir.</p></div><div class="actions"><button type="button" class="secondary" id="closeBatchReceipt">Kapat</button><button type="button" class="primary" id="printBatchReceipt">Yazdır / PDF</button></div>`;$('#closeBatchReceipt').onclick=()=>$('#modal').close();$('#printBatchReceipt').onclick=()=>window.print();$('#modal').showModal()}

async function readDocumentAttachment(file,types){if(!file)return null;if(file.size>3*1024*1024)throw Error('Her dosya en fazla 3 MB olabilir.');if(!types.includes(file.type))throw Error('PDF alanına PDF, fotoğraf alanına PNG veya JPEG seçin.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Dosya okunamadı.'));reader.readAsDataURL(file)});return {name:file.name,data}}

function recordFieldGroup(node,kind){if(node.dataset.recordGroup)return node.dataset.recordGroup;if(node.id==='intakeGuarantors')return 'guarantors';if(node.querySelector('[data-property-details]'))return 'assets';const controls=[...(node.matches('input,select,textarea')?[node]:[]),...node.querySelectorAll('input,select,textarea')];const keys=controls.map(el=>el.name||el.id);if(keys.some(k=>['attachment','photoAttachment','clientPhotos','clientPowerOfAttorney'].includes(k)))return 'files';if(keys.some(k=>/^(bankName|bankBranch|accountHolder|iban)$/.test(k)))return 'bank';if(keys.some(k=>/^(city|district|address|address2.*|officeAddress3.*)$/.test(k)))return 'address';if(keys.some(k=>/^(phone.*|referencePhone.*|officePhone.*|phone|email)$/.test(k)))return kind==='client'?'contact':'debtor';if(keys.some(k=>['relatedStaff','receivedBy','recordedBy','deliveredBy','originalDocument','notes','documentStaff','collectionStaff','reference'].includes(k)))return kind==='client'?'staff':'delivery';if(keys.some(k=>['debtor','identity'].includes(k)))return kind==='client'?'general':'debtor';if(kind==='intake'&&(node.id==='typeFields'||node.classList.contains('document-types')||keys.some(k=>['docType','amount','due','issued','serial'].includes(k))))return 'document';return kind==='client'?'general':'document'}
function setupRecordFormTabs(form,kind){if(!form||form.dataset.tabbed)return;form.dataset.tabbed='true';const definitions=kind==='client'?[['general','Müvekkil Bilgileri'],['contact','İletişim'],['address','Adres'],['staff','Personel ve Notlar'],['bank','Banka Bilgileri'],['files','Fotoğraf / Vekâletname']]:[['document','Müvekkil ve Evrak'],['debtor','Borçlu Bilgileri'],['address','Adresler'],['delivery','Teslim ve Personel'],['assets','Tapu / Araç / SGK'],['guarantors','Kefiller'],['files','PDF / Fotoğraf']];const body=form.querySelector('.formbody'),nodes=[];for(const node of [...body.children]){if(node.classList.contains('grid')&&node.id!=='typeFields')nodes.push(...node.children);else nodes.push(node)}const nav=document.createElement('div');nav.className='settings-tabs record-form-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label',kind==='client'?'Müvekkil kayıt bölümleri':'Evrak kayıt bölümleri');const panels=new Map();for(const [key,label] of definitions){const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.formTab=key;button.id=form.id+'-tab-'+key;button.setAttribute('role','tab');button.setAttribute('aria-controls',form.id+'-panel-'+key);nav.append(button);const panel=document.createElement('section');panel.dataset.formPanel=key;panel.id=form.id+'-panel-'+key;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',button.id);const grid=document.createElement('div');grid.className='grid';panel.append(grid);panels.set(key,{panel,grid,button})}for(const node of nodes){if(node.matches('h3.sectiontitle')){node.remove();continue}if(node.classList.contains('notice'))continue;const group=recordFieldGroup(node,kind);if(!node.classList.contains('field'))node.classList.add('full');(panels.get(group)||panels.values().next().value).grid.append(node)}for(const child of [...body.children])if(child.classList.contains('grid')&&!child.children.length)child.remove();body.append(nav);for(const {panel} of panels.values())body.append(panel);function select(key){for(const [k,{panel,button}] of panels){const active=k===key;panel.hidden=!active;button.classList.toggle('selected',active);button.setAttribute('aria-selected',String(active))}form.dataset.activeFormTab=key}for(const [key,{button}] of panels)button.onclick=()=>select(key);form.addEventListener('invalid',event=>{const first=form.querySelector('input:invalid,select:invalid,textarea:invalid')||event.target;const panel=first.closest('[data-form-panel]');if(panel)select(panel.dataset.formPanel);if(event.target!==first)event.preventDefault()},true);form.addEventListener('reset',()=>select(definitions[0][0]));select(definitions[0][0])}

let parkingLastDay=businessDate();setInterval(()=>{const today=businessDate();if(today===parkingLastDay)return;parkingLastDay=today;db.docs.forEach(d=>applyParkingFee(d,today));if(page==='intake')document.getElementById('intakeForm')?._refreshParkingFee?.();else if(!document.querySelector('dialog[open]')&&['home','clients','documents'].includes(page))render()},60000);

function borrowerAssignmentMarkup(d,isAdmin){const current=personnel.find(p=>p.id===d.relatedStaff),name=current?.name||d.relatedStaffName||'Atanmadı';if(!isAdmin)return esc(name);return `<div><small>Mevcut: ${esc(name)}${current&&current.active!==true?' (pasif)':''}</small><select data-assignment-for="${d.id}" aria-label="${esc(d.debtor)} dosya sorumlusu"><option value="">Aktif personel seçin</option>${personnel.filter(p=>p.active===true).map(p=>`<option value="${esc(p.id)}" ${p.id===d.relatedStaff?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button type="button" class="link" data-save-assignment="${d.id}">Sorumlu Ata</button></div>`}
