function filteredBorrowers(docs,filters,status,query,isAdmin){const norm=normalizeSearch;return docs.filter(d=>{if(status!=='Tümü'&&debtorStatus(d)!==status)return false;if(!matchesGlobalSearch(d,db.clients.find(c=>c.id===d.client),query))return false;if(filters.client&&d.client!==filters.client||filters.type&&docType(d)!==filters.type)return false;if(filters.staff&&(filters.staff==='unassigned'?!!d.relatedStaff:d.relatedStaff!==filters.staff))return false;if(filters.identity&&!String(d.identity||'').includes(filters.identity.trim()))return false;if(filters.phone&&!borrowerPhoneMatches(d,filters.phone))return false;if(filters.enforcementOffice&&!norm(d.enforcementOffice).includes(norm(filters.enforcementOffice).trim()))return false;if(filters.enforcementFileNumber&&!norm(d.enforcementFileNumber).includes(norm(filters.enforcementFileNumber).trim()))return false;if(filters.number&&!norm(d.number).includes(norm(filters.number).trim())||filters.debtor&&!norm(d.debtor).includes(norm(filters.debtor).trim()))return false;const tracking=borrowerTrackingDate(d);if(filters.trackingStart&&(!tracking||tracking<filters.trackingStart)||filters.trackingEnd&&(!tracking||tracking>filters.trackingEnd))return false;if(filters.dueStart&&(!d.due||d.due<filters.dueStart)||filters.dueEnd&&(!d.due||d.due>filters.dueEnd))return false;const amount=isAdmin?docFinance(d).target:financeCents(d.amount);return (filters.minCents===''||filters.minCents==null||amount>=filters.minCents)&&(filters.maxCents===''||filters.maxCents==null||amount<=filters.maxCents)})}
function borrowerFilterMarkup(){const f=borrowerFilters;return `<form id="borrowerFilterForm" class="formbody"><div class="grid"><label class="field">Müvekkil<select name="client" data-optional="true"><option value="">Tüm Müvekkiller</option>${db.clients.map(c=>`<option value="${esc(c.id)}" ${f.client===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Evrak Türü<select name="type" data-optional="true"><option value="">Tüm Evrak Türleri</option>${Object.keys(documentTypes).map(t=>`<option value="${esc(t)}" ${f.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="field">Evrak No<input name="number" data-optional="true" value="${esc(f.number)}"></label><label class="field">Borçlu Adı<input name="debtor" data-optional="true" value="${esc(f.debtor)}"></label><label class="field">TC Kimlik / Vergi No<input name="identity" inputmode="numeric" data-optional="true" value="${esc(f.identity||'')}" placeholder="TC kimlik veya vergi numaras?"></label><label class="field">Telefon Numarası<input name="phone" type="tel" data-optional="true" value="${esc(f.phone||'')}" placeholder="Telefon numarası ara…"></label><label class="field">İcra Dairesi<input name="enforcementOffice" data-optional="true" value="${esc(f.enforcementOffice||'')}" placeholder="İcra dairesi ara…"></label><label class="field">İcra Dosya Numarası<input name="enforcementFileNumber" data-optional="true" value="${esc(f.enforcementFileNumber||'')}" placeholder="Örn. 2026/1234"></label><label class="field">Dosya Sorumlusu<select name="staff" data-optional="true"><option value="">Tüm Personeller</option><option value="unassigned" ${f.staff==='unassigned'?'selected':''}>Atanmamış Dosyalar</option>${personnel.map(p=>`<option value="${esc(p.id)}" ${f.staff===p.id?'selected':''}>${esc(p.name)}${p.active?'':' (pasif)'}</option>`).join('')}</select></label><label class="field">En Az Tutar (TL)<input name="minAmount" inputmode="decimal" data-optional="true" placeholder="0,00" value="${esc(f.minAmount)}"></label><label class="field">En Çok Tutar (TL)<input name="maxAmount" inputmode="decimal" data-optional="true" placeholder="0,00" value="${esc(f.maxAmount)}"></label><label class="field">Takip Tarihi Başlangıcı<input type="date" name="trackingStart" data-optional="true" value="${esc(f.trackingStart||'')}"></label><label class="field">Takip Tarihi Bitişi<input type="date" name="trackingEnd" data-optional="true" value="${esc(f.trackingEnd||'')}"></label><label class="field">Vade Başlangıcı<input type="date" name="dueStart" data-optional="true" value="${esc(f.dueStart)}"></label><label class="field">Vade Bitişi<input type="date" name="dueEnd" data-optional="true" value="${esc(f.dueEnd)}"></label></div><div class="toolbar" style="margin-top:16px"><button class="primary" type="submit">Filtrele</button><button class="secondary" type="button" id="clearBorrowerFilters">Tüm Filtreleri Temizle</button></div></form>`}
function bindBorrowerFilters(){const form=$('#borrowerFilterForm');for(const name of ['minAmount','maxAmount'])form.elements[name].oninput=()=>form.elements[name].setCustomValidity('');form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const next=Object.fromEntries(new FormData(form));for(const [input,key] of [['minAmount','minCents'],['maxAmount','maxCents']]){const parsed=parseAmountInput(next[input]);if(parsed===null||parsed!==''&&Number(parsed)<0){form.elements[input].setCustomValidity('Geçerli, sıfır veya pozitif tutar girin.');form.elements[input].reportValidity();return}next[key]=parsed===''?'':financeCents(parsed);if(parsed!==''){next[input]=formatAmountInput(parsed);form.elements[input].value=next[input]}}if(next.minCents!==''&&next.maxCents!==''&&next.minCents>next.maxCents)return toast('En az tutar, en çok tutardan büyük olamaz.');if(next.trackingStart&&next.trackingEnd&&next.trackingStart>next.trackingEnd)return toast('Takip bitiş tarihi başlangıçtan önce olamaz.');if(next.dueStart&&next.dueEnd&&next.dueStart>next.dueEnd)return toast('Vade başlangıcı bitişten sonra olamaz.');borrowerFilters=next;docRows()};$('#clearBorrowerFilters').onclick=()=>{for(const key of Object.keys(debtorColumnFilters))delete debtorColumnFilters[key];borrowerFilters={client:'',type:'',number:'',debtor:'',identity:'',staff:'',minAmount:'',maxAmount:'',minCents:'',maxCents:'',dueStart:'',dueEnd:''};documents()}}

