function clientDebtorIdentityConflict(kind,id,value,borrowerName){const identity=v=>String(v||'').replace(/\s/g,''),name=v=>String(v||'').trim().replace(/\s+/g,' ').toLocaleUpperCase('tr'),key=identity(value);if(!/^\d{10,11}$/.test(key))return '';const conflict=kind==='client'?db.clients.some(c=>c.id!==id&&identity(c.identity)===key)||db.docs.some(d=>identity(d.identity)===key):db.clients.some(c=>identity(c.identity)===key)||db.docs.some(d=>d.id!==id&&identity(d.identity)===key&&(!name(borrowerName)||name(d.debtor)!==name(borrowerName)));return conflict?'Bu TC kimlik / vergi numarası başka bir müvekkil veya borçluda kayıtlı. Kayıt yapılamadı.':''}

