const closeButtonObserver=new MutationObserver(alignCloseButtons);closeButtonObserver.observe(document.body,{childList:true,subtree:true});alignCloseButtons();

function setupDateCalendar(original,proxy,kind){const wrap=document.createElement('span');wrap.className='date-calendar-control';proxy.before(wrap);wrap.append(proxy);const button=document.createElement('button');button.type='button';button.className='date-calendar-button';button.textContent='▦';button.setAttribute('aria-label',kind==='month'?'Ay takvimini aç':'Takvimi aç');button.title='Takvimden seç';const picker=document.createElement('input');picker.type=kind;picker.dataset.dateUi='calendar';picker.dataset.optional='true';picker.className='date-calendar-native';picker.tabIndex=-1;picker.setAttribute('aria-label',kind==='month'?'Takvimden ay seç':'Takvimden tarih seç');wrap.append(button,picker);function open(){if(original.disabled||original.readOnly)return;picker.value=original.value;picker.min=original.min||'';picker.max=original.max||'';picker.disabled=false;try{if(picker.showPicker)picker.showPicker();else{picker.classList.add('calendar-fallback');picker.focus();picker.click()}}catch{picker.classList.add('calendar-fallback');picker.focus()}}button.onclick=open;
const manualDateEntry = (original.name === 'issued' && original.form?.id === 'intakeForm') ||
  (original.name === 'date' && original.form?.id === 'financeEntry');
if (!manualDateEntry) proxy.addEventListener('click', open);
picker.addEventListener('change',()=>{original.value=picker.value;proxy.value=displayDate(picker.value);proxy.setCustomValidity('');picker.classList.remove('calendar-fallback');original.dispatchEvent(new Event('change',{bubbles:true}))});original._calendarButton=button;original._calendarPicker=picker;button.disabled=original.disabled||original.readOnly;picker.disabled=button.disabled}

function sameIdentityDocuments(record,documents){const normalize=value=>String(value||'').replace(/\s/g,'');const key=normalize(record.identity);return /^\d{10,11}$/.test(key)?documents.filter(d=>d.id!==record.id&&normalize(d.identity)===key):[]}
function offerSameIdentityChain(d){const matches=sameIdentityDocuments(d,db.docs);if(!matches.length)return;let dialog=document.getElementById('sameIdentityChainDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='sameIdentityChainDialog';document.body.append(dialog)}dialog.innerHTML='<div class="panelhead"><h2>Aynı TC ile Kayıtlı Dosya Bulundu</h2></div><div class="formbody"><p>Yeni kaydettiğiniz <strong>'+esc(d.number)+'</strong> dosyasının TC numarası aşağıdaki dosyalarla aynı. Zincir yapayım mı?</p>'+matches.map(x=>'<label class="settings-check"><input type="checkbox" data-identity-chain="'+esc(x.id)+'" checked> '+esc(x.number)+' · '+esc(x.debtor)+' · '+esc(debtorStatus(x))+'</label>').join('')+'<p>Dosya kaydedildi. Zincir yapmadan da devam edebilirsiniz.</p></div><div class="actions"><button type="button" class="secondary" data-skip-chain>Hayır, Devam Et</button><button type="button" class="primary" data-confirm-chain>Evet, Zincir Yap</button></div>';dialog.querySelector('[data-skip-chain]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm-chain]').onclick=()=>{const selected=[...dialog.querySelectorAll('[data-identity-chain]:checked')];if(!selected.length)return toast('Bağlamak istediğiniz dosyayı seçin.',dialog);const button=dialog.querySelector('[data-confirm-chain]');button.disabled=true;try{for(const option of selected){const result=authApi('/api/documents/chain','POST',{documentId:d.id,targetId:option.dataset.identityChain,action:'add'});for(const record of result.documents){const existing=db.docs.find(x=>x.id===record.id);if(existing)Object.assign(existing,record)}}dialog.close();toast('Dosyalar zincir yapılarak kaydedildi.')}catch(error){toast(error.message,dialog)}finally{button.disabled=false}};dialog.showModal()}

function upgradePhoneInputs(){document.querySelectorAll('input[type="tel"],input[name]').forEach(input=>{if(input.closest('#borrowerFilterForm')||input.type==='search'||!(/^tel$/.test(input.type)||/^(phone\d*|referencePhone\d*|officePhone\d*|telephone)$/i.test(input.name)))return;if(!input.dataset.phoneFormat){input.dataset.phoneFormat='true';input.placeholder='0 (545) 967 29 77';input.inputMode='tel';input.addEventListener('blur',()=>input.value=formatPhoneNumber(input.value));input.addEventListener('change',()=>input.value=formatPhoneNumber(input.value));input.addEventListener('input',()=>{let digits=input.value.replace(/\D/g,'');if(digits.length===10&&!digits.startsWith('0')||digits.length===11&&digits.startsWith('0')||digits.length===12&&digits.startsWith('90'))input.value=formatPhoneNumber(input.value)});}if(document.activeElement!==input)input.value=formatPhoneNumber(input.value)})}
const phoneFormatObserver=new MutationObserver(upgradePhoneInputs);phoneFormatObserver.observe(document.body,{childList:true,subtree:true});document.addEventListener('submit',e=>{e.target.querySelectorAll('input[data-phone-format]').forEach(input=>input.value=formatPhoneNumber(input.value))},true);upgradePhoneInputs();

function upgradeIbanInputs(){document.querySelectorAll('input[name]').forEach(input=>{if(!/iban/i.test(input.name))return;if(!input.dataset.ibanFormat){input.dataset.ibanFormat='true';input.maxLength=42;input.placeholder='TR00 0000 0000 0000 0000 0000 00';input.addEventListener('input',()=>{const end=input.selectionStart===input.value.length;const value=formatIbanNumber(input.value);if(input.value!==value){input.value=value;if(end)input.setSelectionRange(value.length,value.length)}});input.addEventListener('blur',()=>input.value=formatIbanNumber(input.value))}if(document.activeElement!==input)input.value=formatIbanNumber(input.value)})}
const ibanFormatObserver=new MutationObserver(upgradeIbanInputs);ibanFormatObserver.observe(document.body,{childList:true,subtree:true});upgradeIbanInputs();
